WHO = {'column': [('psilotem', 241160), ('rocieesof', 0), ('apriddoum', 241348), ('eincceyeben', 241348), ('eincicro', 241604), ('qudmicro', 0), ('einlddldoum', 241796), ('psiloceyeben', 241924)], 'tower': [('zedldoum', 241160), ('einlddldoum', 0), ('psilotem', 245230), ('vathllesof', 0), ('shaceesof', 248849), ('shacdmolum', 249292), ('zesol', 249484), ('viun', 249484)], 'tree': [('aprilfools', 242876), ('psiloeyeben', 243512), ('aprilfools', 247835), ('aprilfools', 0), ('psiloeyeben', 0), ('aprilfools', 250183), ('aprileyeben', 250183), ('aprileyeben', 250691)], 'bridge': [('einccllya', 242876), ('alphafoldmicro', 243512), ('shaclddmicro', 244654), ('shacldmicro', 0), ('shacldmicro', 245673), ('shaclddmicro', 0), ('shaclddmicro', 246373), ('shacldmicro', 0)], 'temple': [('orhldoum', 243004), ('vathlesof', 243004), ('shacddmicro', 244974), ('eincdsol', 246117), ('aprilsol', 0), ('vathldicro', 0), ('apridcdevi', 253046), ('orhldoum', 0)], 'manor': [('psilodmicro', 243768), ('einsof', 0), ('psiloceyeben', 246373), ('einccum', 0), ('orhldoum', 0), ('psilodmicro', 255083)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW197(OracleReleaseRuntimeW195):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
